phase4_shot_coverage <- function(con) {
  DBI::dbExecute(con,"ATTACH 'data/processed/phase4/baseline.duckdb' AS phase3_frozen (READ_ONLY)");on.exit(DBI::dbExecute(con,'DETACH phase3_frozen'),add=TRUE)
  z<-DBI::dbGetQuery(con,"WITH b AS (SELECT g.season,sum(t.fga) canonical_box_fga FROM team_box_scores t JOIN games g USING(game_id) GROUP BY g.season), old_c AS (SELECT season,count(*) certified_before,count(DISTINCT game_id) certified_games_before FROM phase3_frozen.main.certified_shot_attempts GROUP BY season), new_c AS (SELECT season,count(*) certified_after,count(DISTINCT game_id) certified_games_after,count(*) FILTER(WHERE coordinate_status='observed') certified_with_coordinates FROM certified_shot_attempts GROUP BY season), old_s AS (SELECT g.season,count(*) canonical_before FROM phase3_frozen.main.shot_attempts s JOIN games g USING(game_id) GROUP BY g.season), new_s AS (SELECT g.season,count(*) canonical_after FROM shot_attempts s JOIN games g USING(game_id) GROUP BY g.season) SELECT b.*,coalesce(old_c.certified_before,0) certified_before,coalesce(new_c.certified_after,0) certified_after,coalesce(old_c.certified_games_before,0) certified_games_before,coalesce(new_c.certified_games_after,0) certified_games_after,coalesce(old_s.canonical_before,0) canonical_before,coalesce(new_s.canonical_after,0) canonical_after,coalesce(new_c.certified_with_coordinates,0) certified_with_coordinates FROM b LEFT JOIN old_c USING(season) LEFT JOIN new_c USING(season) LEFT JOIN old_s USING(season) LEFT JOIN new_s USING(season) ORDER BY b.season")
  z$additional_certified<-z$certified_after-z$certified_before;z$additional_certified_games<-z$certified_games_after-z$certified_games_before;z$additional_canonical<-z$canonical_after-z$canonical_before;z$certified_share_before<-z$certified_before/z$canonical_box_fga;z$certified_share_after<-z$certified_after/z$canonical_box_fga
  utils::write.csv(z,'docs/phase4/shot_coverage_before_after.csv',row.names=FALSE);invisible(z)
}
